          <p class="support-copy">
            Send us your details and we’ll get back to you as soon as possible.
          </p>
        </div>
        <div id="app"></div>
      </section>
    </main>

    <script>
      const state = {
        submitted: false,
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
      };

      const escapeHtml = (value) =>
        String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");

      const validate = () => {
        const errors = {};

        if (!state.values.fullName.trim()) {
          errors.fullName = "Full name is required.";
        }

        if (!state.values.email.trim()) {
          errors.email = "Email address is required.";
        } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(state.values.email.trim())) {
          errors.email = "Enter a valid email address.";
        }

        return errors;
      };

      const Field = ({ id, label, type, name, required = false, helper = "", value = "", error = "" }) => `
        <div class="form-field">
          <label for="${id}">${escapeHtml(label)}${required ? ' <span aria-hidden="true">*</span>' : ""}</label>
          <input
            id="${id}"
            name="${name}"
            type="${type}"
            value="${escapeHtml(value)}"
            ${required ? "required" : ""}
            ${type === "email" ? 'autocomplete="email"' : ""}
            ${type === "tel" ? 'autocomplete="tel"' : ""}
          />
          ${helper ? `<p class="field-help" id="${id}-help">${escapeHtml(helper)}</p>` : ""}
          <p class="field-error" id="${id}-error" aria-live="polite">${escapeHtml(error)}</p>
        </div>
      `;

      const App = () => {
        const errors = state.submitted ? validate() : {};
        const success = state.submitted && Object.keys(errors).length === 0;

        return `
          <form id="support-form" novalidate>
            <div class="form-grid">
              ${Field({
                id: "fullName",
                label: "Full name",
                type: "text",
                name: "fullName",
                required: true,
                value: state.values.fullName,
                error: errors.fullName || "",
              })}
              ${Field({
                id: "email",
                label: "Email address",
                type: "email",
                name: "email",
                required: true,
                value: state.values.email,
                error: errors.email || "",
              })}
              ${Field({
                id: "phone",
                label: "Phone number",
                type: "tel",
                name: "phone",
                helper: "Optional. Use a format like +1 (555) 123-4567.",
                value: state.values.phone,
                error: "",
              })}
            </div>
            <div class="form-actions">
              <button type="submit">Submit request</button>
            </div>
            ${success ? '<div class="success" role="status">Thanks — your request has been submitted.</div>' : ""}
          </form>
        `;
      };

      const render = () => {
        document.getElementById("app").innerHTML = App();

        const form = document.getElementById("support-form");
        form.addEventListener("submit", (event) => {
          event.preventDefault();
          state.submitted = true;

          const data = new FormData(form);
          state.values = {
            fullName: data.get("fullName")?.toString() ?? "",
            email: data.get("email")?.toString() ?? "",
            phone: data.get("phone")?.toString() ?? "",
          };

          render();
        });

        ["fullName", "email", "phone"].forEach((field) => {
          const input = document.getElementById(field);
          input.addEventListener("input", (event) => {
            state.values[field] = event.target.value;
          });
        });
      };

      render();
    </script>
  </body>
</html>
